import java.io.InputStream;
import java.io.OutputStream;
import java.io.IOException;

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[32768];
        private int head = 0;
        private int tail = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (head >= tail) {
                head = 0;
                tail = in.read(buffer, 0, buffer.length);
                if (tail <= 0) return -1;
            }
            return buffer[head++];
        }

        public int nextInt() throws IOException {
            int c = read();
            while (c <= ' ') {
                if (c == -1) return -1;
                c = read();
            }
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int res = 0;
            while (c >= '0' && c <= '9') {
                res = res * 10 + (c - '0');
                c = read();
            }
            return res * sign;
        }
    }

    static class FastWriter {
        private final OutputStream out;
        private final byte[] buffer = new byte[32768];
        private int head = 0;

        public FastWriter(OutputStream out) {
            this.out = out;
        }

        public void write(byte b) throws IOException {
            if (head >= buffer.length) {
                flush();
            }
            buffer[head++] = b;
        }

        public void printInt(int val) throws IOException {
            if (val == 0) {
                write((byte) '0');
                return;
            }
            if (val < 0) {
                write((byte) '-');
                val = -val;
            }
            byte[] digits = new byte[11];
            int len = 0;
            while (val > 0) {
                digits[len++] = (byte) ('0' + (val % 10));
                val /= 10;
            }
            for (int i = len - 1; i >= 0; i--) {
                write(digits[i]);
            }
        }

        public void flush() throws IOException {
            if (head > 0) {
                out.write(buffer, 0, head);
                head = 0;
            }
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        FastWriter writer = new FastWriter(System.out);

        int n = scanner.nextInt();
        if (n <= 0) return;

        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = scanner.nextInt();
        }

        int INF = 1_000_000_000;
        int[] left = new int[n];
        int[] right = new int[n];

        // Passada da esquerda para a direita
        for (int i = 0; i < n; i++) {
            int fromPrev = (i > 0 && left[i - 1] < INF) ? left[i - 1] + 1 : INF;
            if (a[i] != -1) {
                left[i] = Math.min(a[i], fromPrev);
            } else {
                left[i] = fromPrev;
            }
        }

        // Passada da direita para a esquerda
        for (int i = n - 1; i >= 0; i--) {
            int fromNext = (i < n - 1 && right[i + 1] < INF) ? right[i + 1] + 1 : INF;
            if (a[i] != -1) {
                right[i] = Math.min(a[i], fromNext);
            } else {
                right[i] = fromNext;
            }
        }

        // A resposta para cada degrau é o mínimo entre as restrições da esquerda e da direita
        for (int i = 0; i < n; i++) {
            int ans = Math.min(left[i], right[i]);
            writer.printInt(ans);
            if (i < n - 1) {
                writer.write((byte) ' ');
            } else {
                writer.write((byte) '\n');
            }
        }

        writer.flush();
    }
}
